async function challengeCount(sql, userId, key) {
	const start = lagosDayStart();
	if (key === "chat") {
		const rows = await sql`select count(*)::int as n from messages where sender_id = ${userId} and created_at >= ${start}`;
		return Number(rows[0]?.n ?? 0);
	}
	if (key === "post") {
		const rows = await sql`select count(*)::int as n from posts where author_id = ${userId} and created_at >= ${start}`;
		return Number(rows[0]?.n ?? 0);
	}
	const rows = await sql`select count(*)::int as n from post_views where viewer_id = ${userId} and started_at >= ${start}`;
	return Number(rows[0]?.n ?? 0);
}
